events = recurring_ical_events.of(cal).between(start_dt, end_dt)

busy_intervals = []
for ev in events:
    b_start = ev.decoded('dtstart')
    b_end = ev.decoded('dtend')
    if isinstance(b_start, datetime):
        b_start = b_start.replace(tzinfo=None)
        b_end = b_end.replace(tzinfo=None)
    else:
        b_start = datetime(b_start.year, b_start.month, b_start.day, 0, 0)
        b_end = datetime(b_start.year, b_start.month, b_start.day, 0, 0) + timedelta(days=1)
    busy_intervals.append((b_start, b_end))

